arguments.command:
curl -s -X POST https://slack.com/api/conversations.list -H "Authorization: Bearer <TOKEN>" -d "token=<TOKEN>&types=public_channel,private_channel&limit=1000" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERR',d); sys.exit(1)
for c in d['channels']:
    topic=c.get('topic',{}).get('value','')
    if 'postmortem' in topic.lower() or 'post-mortem' in topic.lower():
        print(c['id'], '|', c.get('name'), '| archived:', c.get('is_archived'), '| topic:', topic)
"

